{
  "title": "Annual Rainfall Summary",
  "body": "<div class="rainfall-card">
  <figure class="figure-container">
    <ml-embed ref="@tool:3fa9c21:out"></ml-embed>
    <figcaption class="figure-caption">Monthly precipitation overview</figcaption>
  </figure>

  <div class="stats-grid">
    <div class="stat-box total-box">
      <span class="stat-label">Yearly Total</span>
      <span class="stat-value" id="yearly-total">—</span>
    </div>

    <div class="stat-box wettest-box">
      <span class="stat-label">Three Wettest Months</span>
      <ol class="wettest-list" id="top-months">
        <li>Loading…</li>
      </ol>
    </div>
  </div>
</div>",
  "css": ".rainfall-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: #ffffff;
  color: #1f2937;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box;
}

.figure-container {
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  overflow: hidden;
}

.figure-container ml-embed {
  width: 100%;
  display: flex;
  justify-content: center;
}

.figure-caption {
  padding: 8px 12px;
  font-size: 0.85rem;
  color: #6b7280;
  text-align: center;
  font-style: italic;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.stat-box {
  background: #f3f4f6;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  color: #4b5563;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1d4ed8;
}

.wettest-list {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.9rem;
  color: #374151;
}

.wettest-list li {
  line-height: 1.3;
}

.wettest-list .month-name {
  font-weight: 600;
}

.wettest-list .month-val {
  color: #2563eb;
  margin-left: 4px;
}",
  "scripts": [
    "const csv = ml.dereference("@tool:7be01d4:out") || "";
const rawLines = csv.trim().split("\n").map(line => line.trim()).filter(line => line.length > 0);
const lines = rawLines[0]?.toLowerCase().startsWith("month") ? rawLines.slice(1) : rawLines;

const records = lines.map(line => {
  const parts = line.split(",").map(p => p.trim());
  return {
    month: parts[0] ?? "",
    mm: Number(parts[1]) || 0
  };
});

const total = records.reduce((acc, cur) => acc + cur.mm, 0);
const sorted = records.slice().sort((a, b) => b.mm - a.mm);
const topThree = sorted.slice(0, 3);

const totalEl = root.querySelector("#yearly-total");
if (totalEl) {
  totalEl.textContent = `${Math.round(total * 10) / 10} mm`;
}

const listEl = root.querySelector("#top-months");
if (listEl) {
  listEl.replaceChildren();
  topThree.forEach(item => {
    const li = root.create("li");
    const nameSpan = root.create("span");
    nameSpan.classList.add("month-name");
    nameSpan.textContent = item.month;

    const valSpan = root.create("span");
    valSpan.classList.add("month-val");
    valSpan.textContent = `(${item.mm} mm)`;

    li.append(nameSpan);
    li.append(valSpan);
    listEl.append(li);
  });
}"
  ]
}
